let enabled = global.get('mqtt.enabled', 'default') || false;
let discovery = global.get('mqtt.homeassistant', 'default') || '';
let topic = global.get('mqtt.topic', 'default') || '';

if (!enabled || topic === '') {

    return;
}

// Home Assistant rejects empty or 'none' device_class, state_class and unit
function clean(payload) {
    for (const k of ['device_class', 'state_class', 'unit_of_measurement']) {
        if (payload[k] === undefined || payload[k] === null || payload[k] === '' || payload[k] === 'none') {
            delete payload[k];
        }
    }

    return payload;
}

let source = 'teleinfo';
let describe = global.get('describe', 'memoryOnly') || {};

// Options labels in the language of the MQTT configuration
const lang = global.get('mqtt.lang', 'default') || 'fr';
const words = (describe.translate || {})[lang] || {};
const tr = s => typeof s === 'string' && typeof words[s] === 'string' ? words[s] : s;
const trOptions = o => { let r = {}; for (const k in (o || {})) { r[k] = tr(o[k]); } return r; };
// Home Assistant template mapping a value with a dictionary
const haMap = m => '{{ ' + JSON.stringify(m) + '[value] | default(value) }}';

// Entities with a list of values (key is the raw value)
const enums = { 'OPTARIF': describe.optarif, 'PTEC': describe.ptec, 'DEMAIN': describe.demain };


// Source definition
let srcMsg = {
    'topic': [topic, 'discovery', source].join('/'),
    'payload': describe.app,
    'qos': 0,
    'retain': true
};

node.send([srcMsg]);

let tics = global.get('controls', 'memoryOnly') || {};
for (const port in tics) {
    let id = tics[port]['ADCO']['raw'];
    for (const k in describe.discovery_value_template) {

        if (id !== '') {
            // DKNR discovery
            let dknrMsg = {
                'topic': [topic, 'discovery', source, id, k].join('/'),
                'payload': {
                    'name': describe.names[k],
                    'group': 'sensor',
                    'type': typeof enums[k] === 'object' ? 'enum' : (describe.units[k] === '' ? 'text' : 'number'),
                    'unit': describe.units[k],
                    'value': describe.units[k] === '' ? '' : 0,
                    'options': typeof enums[k] === 'object' ? trOptions(enums[k]) : {}
                },
                'qos': 0,
                'retain': true
            };

            node.send([dknrMsg]);
        }

        // Home assistant discovery
        if (discovery !== "" && (describe.type[k] === 'sensor' || typeof enums[k] === 'object')) {
            let haMsg = {
                'topic': discovery + '/sensor/' + source + '/' + id + '_' + k + '/config',
                'payload': {
                    "unique_id": ['dknr', source, id, k].join('_'),
                    "name": describe.names[k],
                    "state_topic": [topic, 'get', source, id, k].join('/'),
                    "state_class": describe.discovery_state_class[k],
                    "device_class": describe.discovery_device_class[k],
                    "unit_of_measurement": describe.units[k],
                    "device": {
                        "identifiers": [
                            id
                        ],
                        "manufacturer": "Enedis",
                        "model": "teleinfo_" + id,
                        "name": "Teleinfo " + id
                    }
                }
            };

            // list of values: DKNR value is the raw key, show the label
            // (text sensor rather than enum, an unknown meter value would be refused by Home Assistant)
            if (typeof enums[k] === 'object') {
                delete haMsg.payload.state_class;
                delete haMsg.payload.device_class;
                delete haMsg.payload.unit_of_measurement;
                haMsg.payload.value_template = haMap(trOptions(enums[k]));
            }

            clean(haMsg.payload);

            node.send([haMsg]);
        }
    }

    // Reading fault (watchdog), binary 0 / 1
    if (id !== '') {
        node.send([{
            'topic': [topic, 'discovery', source, id, 'FAULT'].join('/'),
            'payload': {
                'name': describe.names['FAULT'],
                'group': 'sensor',
                'type': 'binary',
                'unit': '',
                'value': 0,
                'options': {}
            },
            'qos': 0,
            'retain': true
        }]);

        if (discovery !== '') {
            node.send([{
                'topic': discovery + '/binary_sensor/' + source + '/' + id + '_FAULT/config',
                'payload': {
                    'unique_id': ['dknr', source, id, 'FAULT'].join('_'),
                    'name': describe.names['FAULT'],
                    'state_topic': [topic, 'get', source, id, 'FAULT'].join('/'),
                    'payload_on': '1',
                    'payload_off': '0',
                    'device_class': 'problem',
                    'entity_category': 'diagnostic',
                    'device': {
                        'identifiers': [
                            id
                        ],
                        'manufacturer': 'Enedis',
                        'model': 'teleinfo_' + id,
                        'name': 'Teleinfo ' + id
                    }
                },
                'qos': 0,
                'retain': true
            }]);
        }
    }
}

return;

const topic = global.get('mqtt.topic', 'default') || '';
const source = 'teleinfo';
const sn = msg.payload.ADCO.raw || '';

if (topic === '' || sn === '') {

    return;
}

// PREFERRED first: it is computed from PTEC and must be known before PTEC triggers scenes (tariff routine)
const keys = Object.keys(msg.payload).sort((a, b) => (b === 'PREFERRED') - (a === 'PREFERRED'));
for (const k of keys) {
    if (flow.get('last["' + sn + '_' + k + '"]', 'memoryOnly') !== msg.payload[k]['raw']) {
        flow.set('last["' + sn + '_' + k + '"]', msg.payload[k]['raw'], 'memoryOnly');
        let newMsg = {
            'topic': [topic, 'get', source, sn, k].join('/'),
            'payload': msg.payload[k]['raw']
        };

        node.send([newMsg]);
    }
}

return;

// Write teleinfo values to InfluxDB (one point per meter and per minute)
const url = (env.get('DKNR_INFLUX_URL') || 'http://dknr_teleinfo_influxdb:8086').replace(/\/+$/, '');
const token = env.get('DKNR_INFLUX_TOKEN') || 'dknr-teleinfo-influxdb-token';
const org = env.get('DKNR_INFLUX_ORG') || 'dknr';
const bucket = env.get('DKNR_INFLUX_BUCKET') || 'teleinfo';
const interval = 60000;

if (url === '' || token === '') {
    node.status({ fill: 'grey', shape: 'ring', text: 'InfluxDB non configuré' });
    return null;
}

const p = msg.payload || {};
const adco = (p.ADCO && p.ADCO.raw) ? String(p.ADCO.raw).replace(/[^A-Za-z0-9]/g, '') : '';
if (adco === '') {
    return null;
}

const now = Date.now();
let last = context.get('last', 'memoryOnly') || {};
if (last[adco] && now - last[adco] < interval) {
    return null;
}

// custom or descriptive entries are not stored
const skip = ['ADCO', 'HCHT', 'NAME', 'LOCATION', 'PORT', 'PREFERRED'];
let fields = [];
for (const k in p) {
    if (skip.includes(k) || !/^[A-Z0-9]+$/.test(k) || typeof p[k] !== 'object') {
        continue;
    }
    const v = p[k].value;
    if (typeof v === 'number' && Number.isFinite(v)) {
        fields.push(k + '=' + (Number.isInteger(v) ? v + 'i' : v));
    } else if (typeof v === 'string' && v !== '') {
        fields.push(k + '="' + v.replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"');
    }
}
if (fields.length === 0) {
    return null;
}

last[adco] = now;
context.set('last', last, 'memoryOnly');

return {
    'method': 'POST',
    'url': url + '/api/v2/write?org=' + encodeURIComponent(org) + '&bucket=' + encodeURIComponent(bucket) + '&precision=s',
    'headers': {
        'Authorization': 'Token ' + token,
        'Content-Type': 'text/plain; charset=utf-8'
    },
    'payload': 'teleinfo,adco=' + adco + ' ' + fields.join(',') + ' ' + Math.floor(now / 1000),
    'adco': adco
};

// warn only when the write state changes, not every minute
const ok = msg.statusCode === 204;
let error = '';
if (!ok) {
    error = String(msg.statusCode || msg.error || 'erreur');
    try { error = JSON.parse(msg.payload).message || error; } catch (e) { }
}
if (ok) {
    node.status({ fill: 'green', shape: 'dot', text: msg.adco + ' ' + new Date().toLocaleTimeString('fr-FR') });
} else {
    node.status({ fill: 'red', shape: 'ring', text: String(error).slice(0, 60) });
}
if (context.get('ok', 'memoryOnly') !== ok) {
    context.set('ok', ok, 'memoryOnly');
    if (ok) node.log('InfluxDB write ok');
    else node.warn('InfluxDB write failed: ' + error);
}

return null;

// Start a history request: first ask InfluxDB which meters it knows
const url = (env.get('DKNR_INFLUX_URL') || 'http://dknr_teleinfo_influxdb:8086').replace(/\/+$/, '');
const token = env.get('DKNR_INFLUX_TOKEN') || 'dknr-teleinfo-influxdb-token';
const org = env.get('DKNR_INFLUX_ORG') || 'dknr';
const bucket = env.get('DKNR_INFLUX_BUCKET') || 'teleinfo';

// a tab change to another page: nothing to do
if (typeof msg.tab === 'string' && msg.tab !== 'history') {
    return null;
}

if (msg.topic === 'select') {
    flow.set('history_adco', String(msg.payload || '').replace(/[^A-Za-z0-9]/g, ''), 'memoryOnly');
}

if (url === '' || token === '') {
    return [null, { 'payload': { 'error': "InfluxDB n'est pas configuré.", 'meters': [], 'periods': [], 'fields': [] } }];
}

const reqid = (flow.get('history_req', 'memoryOnly') || 0) + 1;
flow.set('history_req', reqid, 'memoryOnly');
flow.set('history_parts', {}, 'memoryOnly');

return [{
    'method': 'POST',
    'url': url + '/api/v2/query?org=' + encodeURIComponent(org),
    'headers': {
        'Authorization': 'Token ' + token,
        'Content-Type': 'application/json',
        'Accept': 'application/csv'
    },
    'payload': JSON.stringify({
        'type': 'flux',
        'query': 'import "influxdata/influxdb/schema"\nschema.tagValues(bucket: "' + bucket + '", tag: "adco", start: 2000-01-01T00:00:00Z)',
        'dialect': { 'header': true, 'annotations': [], 'delimiter': ',' }
    }),
    'reqid': reqid,
    'part': 'meters'
}, null];

// Collect InfluxDB answers and compute energy per hour, day, month and year
const url = (env.get('DKNR_INFLUX_URL') || 'http://dknr_teleinfo_influxdb:8086').replace(/\/+$/, '');
const token = env.get('DKNR_INFLUX_TOKEN') || 'dknr-teleinfo-influxdb-token';
const org = env.get('DKNR_INFLUX_ORG') || 'dknr';
const bucket = env.get('DKNR_INFLUX_BUCKET') || 'teleinfo';
const tz = /^[A-Za-z_]+(\/[A-Za-z0-9_+-]+)+$/.test(env.get('TZ') || '') ? env.get('TZ') : 'Europe/Paris';

// energy indexes, in display order
const INDEXES = ['BASE', 'HCHC', 'HCHP', 'EJPHN', 'EJPHPM', 'BBRHCJB', 'BBRHPJB', 'BBRHCJW', 'BBRHPJW', 'BBRHCJR', 'BBRHPJR'];
const PERIODS = [
    { 'key': 'hour', 'title': 'Par heure, 24 dernières heures', 'every': '1h', 'start': 'date.sub(d: 24h, from: date.truncate(t: now(), unit: 1h))' },
    { 'key': 'day', 'title': 'Par jour, 7 derniers jours', 'every': '1d', 'start': 'date.sub(d: 7d, from: date.truncate(t: now(), unit: 1d))' },
    { 'key': 'month', 'title': 'Par mois, 12 derniers mois', 'every': '1mo', 'start': 'date.sub(d: 12mo, from: date.truncate(t: now(), unit: 1mo))' },
    { 'key': 'year', 'title': 'Par an', 'every': '1y', 'start': '2000-01-01T00:00:00Z' }
];
const DAYS = ['dim.', 'lun.', 'mar.', 'mer.', 'jeu.', 'ven.', 'sam.'];
const DAYS_LONG = ['dimanche', 'lundi', 'mardi', 'mercredi', 'jeudi', 'vendredi', 'samedi'];
const MONTHS = ['janv.', 'févr.', 'mars', 'avr.', 'mai', 'juin', 'juil.', 'août', 'sept.', 'oct.', 'nov.', 'déc.'];
const MONTHS_LONG = ['janvier', 'février', 'mars', 'avril', 'mai', 'juin', 'juillet', 'août', 'septembre', 'octobre', 'novembre', 'décembre'];

function pad(n) {
    return String(n).padStart(2, '0');
}

// window key in local time (container TZ)
function keyOf(period, d) {
    switch (period) {
        case 'hour': return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) + 'T' + pad(d.getHours());
        case 'day': return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
        case 'month': return d.getFullYear() + '-' + pad(d.getMonth() + 1);
        default: return String(d.getFullYear());
    }
}

// expected bars, oldest first
function buckets(period, now, firstYear) {
    let res = [];
    if (period === 'hour') {
        let base = new Date(now);
        base.setMinutes(0, 0, 0);
        for (let i = 23; i >= 0; i--) {
            const d = new Date(base.getTime() - i * 3600000);
            const h = d.getHours();
            res.push({ 'key': keyOf(period, d), 'label': h + 'h', 'title': pad(d.getDate()) + '/' + pad(d.getMonth() + 1) + ' de ' + h + 'h à ' + ((h + 1) % 24) + 'h' });
        }
    } else if (period === 'day') {
        for (let i = 6; i >= 0; i--) {
            const d = new Date(now.getFullYear(), now.getMonth(), now.getDate() - i);
            res.push({ 'key': keyOf(period, d), 'label': DAYS[d.getDay()] + ' ' + d.getDate(), 'title': DAYS_LONG[d.getDay()] + ' ' + d.getDate() + ' ' + MONTHS_LONG[d.getMonth()] });
        }
    } else if (period === 'month') {
        for (let i = 11; i >= 0; i--) {
            const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
            res.push({ 'key': keyOf(period, d), 'label': MONTHS[d.getMonth()] + (i === 11 || d.getMonth() === 0 ? ' ' + String(d.getFullYear()).slice(2) : ''), 'title': MONTHS_LONG[d.getMonth()] + ' ' + d.getFullYear() });
        }
    } else {
        for (let y = Math.min(firstYear || now.getFullYear(), now.getFullYear()); y <= now.getFullYear(); y++) {
            res.push({ 'key': String(y), 'label': String(y), 'title': 'Année ' + y });
        }
    }

    return res;
}

// parse InfluxDB CSV (no annotations, one header per table)
function parseCsv(text) {
    let rows = [];
    let header = null;
    for (const raw of String(text || '').split(/\r?\n/)) {
        const line = raw.trim();
        if (line === '') {
            header = null;
            continue;
        }
        const cells = line.split(',');
        if (header === null) {
            header = cells;
            continue;
        }
        let row = {};
        header.forEach((h, i) => { if (h !== '') row[h] = cells[i]; });
        rows.push(row);
    }

    return rows;
}

// energy per field and window: last index minus last index of previous window
function energy(period, rows) {
    let series = {};
    for (const r of rows) {
        const v = Number(r._value);
        const t = new Date(r._time);
        if (!INDEXES.includes(r._field) || !Number.isFinite(v) || isNaN(t.getTime())) {
            continue;
        }
        series[r._field] = series[r._field] || {};
        const k = keyOf(period, t);
        series[r._field][k] = series[r._field][k] || { 't': t.getTime() };
        series[r._field][k][r.agg === 'first' ? 'first' : 'last'] = v;
    }

    let res = {};
    let firstYear = null;
    for (const f in series) {
        res[f] = {};
        let prev = null;
        const wins = Object.entries(series[f]).sort((a, b) => a[1].t - b[1].t);
        for (const [k, w] of wins) {
            const first = w.first !== undefined ? w.first : w.last;
            const last = w.last !== undefined ? w.last : w.first;
            let e = prev !== null ? last - prev : last - first;
            if (e < 0) {
                // meter replaced or index reset
                e = Math.max(0, last - first);
            }
            res[f][k] = e;
            prev = last;
            const y = new Date(w.t).getFullYear();
            firstYear = firstYear === null ? y : Math.min(firstYear, y);
        }
    }

    return { 'values': res, 'firstYear': firstYear };
}

function failure(text) {
    let error = String(msg.statusCode || msg.error || 'erreur');
    try { error = JSON.parse(text).message || error; } catch (e) { }

    return "Erreur InfluxDB : " + error;
}

// stale answer
if (msg.reqid !== flow.get('history_req', 'memoryOnly')) {
    return null;
}

// step 1: meters list, then query the four periods
if (msg.part === 'meters') {
    if (msg.statusCode !== 200) {
        return [null, { 'payload': { 'error': failure(msg.payload), 'meters': [], 'periods': [], 'fields': [] } }];
    }

    // meters known by influxdb and meters currently read
    let meters = new Map();
    const units = global.get('units', 'default') || {};
    const controls = global.get('controls', 'memoryOnly') || {};
    for (const port in controls) {
        const id = controls[port] && controls[port].ADCO ? String(controls[port].ADCO.raw) : '';
        if (id !== '') {
            meters.set(id, units[port] ? units[port].name + ' - ' + units[port].location + ' (' + id + ')' : 'Compteur ' + id);
        }
    }
    for (const r of parseCsv(msg.payload)) {
        if (r._value && !meters.has(r._value)) meters.set(r._value, 'Compteur ' + r._value);
    }

    let adco = flow.get('history_adco', 'memoryOnly') || '';
    if (!meters.has(adco)) {
        adco = meters.keys().next().value || '';
        flow.set('history_adco', adco, 'memoryOnly');
    }

    flow.set('history_meters', Array.from(meters.entries()).map(([value, label]) => ({ 'value': value, 'label': label })), 'memoryOnly');

    if (adco === '') {
        return [null, { 'payload': { 'error': "Aucune donnée enregistrée pour l'instant. Les premières valeurs apparaîtront une minute après la lecture d'un compteur.", 'meters': [], 'periods': [], 'fields': [] } }];
    }

    let out = [];
    for (const p of PERIODS) {
        const query = [
            'import "date"',
            'import "timezone"',
            'option location = timezone.location(name: "' + tz + '")',
            'start = ' + p.start,
            'data = from(bucket: "' + bucket + '")',
            '  |> range(start: start)',
            '  |> filter(fn: (r) => r._measurement == "teleinfo" and r.adco == "' + adco + '")',
            '  |> filter(fn: (r) => r._field =~ /^(' + INDEXES.join('|') + ')$/)',
            'w_first = data |> aggregateWindow(every: ' + p.every + ', fn: first, createEmpty: false, timeSrc: "_start") |> set(key: "agg", value: "first")',
            'w_last = data |> aggregateWindow(every: ' + p.every + ', fn: last, createEmpty: false, timeSrc: "_start") |> set(key: "agg", value: "last")',
            'union(tables: [w_first, w_last])',
            '  |> keep(columns: ["_time", "_field", "_value", "agg"])'
        ].join('\n');
        out.push({
            'method': 'POST',
            'url': url + '/api/v2/query?org=' + encodeURIComponent(org),
            'headers': {
                'Authorization': 'Token ' + token,
                'Content-Type': 'application/json',
                'Accept': 'application/csv'
            },
            'payload': JSON.stringify({ 'type': 'flux', 'query': query, 'dialect': { 'header': true, 'annotations': [], 'delimiter': ',' } }),
            'reqid': msg.reqid,
            'part': p.key,
            'adco': adco
        });
    }
    node.status({ fill: 'blue', shape: 'ring', text: 'requête ' + adco });

    return [out, null];
}

// step 2: collect the four answers
let parts = flow.get('history_parts', 'memoryOnly') || {};
parts[msg.part] = { 'status': msg.statusCode, 'payload': msg.payload };
flow.set('history_parts', parts, 'memoryOnly');
if (PERIODS.some(p => parts[p.key] === undefined)) {
    return null;
}

const now = new Date();
const names = global.get('describe.names', 'memoryOnly') || {};
let error = '';
let present = {};
let periods = [];
for (const p of PERIODS) {
    const part = parts[p.key];
    let computed = { 'values': {}, 'firstYear': null };
    if (part.status === 200) {
        computed = energy(p.key, parseCsv(part.payload));
    } else if (error === '') {
        msg.statusCode = part.status;
        error = failure(part.payload);
    }
    let total = 0;
    const bars = buckets(p.key, now, computed.firstYear).map(b => {
        let values = {};
        let sum = 0;
        for (const f in computed.values) {
            const v = computed.values[f][b.key];
            if (v !== undefined) {
                values[f] = v;
                sum += v;
                present[f] = true;
            }
        }
        total += sum;
        return { 'key': b.key, 'label': b.label, 'title': b.title, 'values': values, 'total': sum };
    });
    periods.push({ 'key': p.key, 'title': p.title, 'bars': bars, 'total': total });
}

const fields = INDEXES.filter(f => present[f]).map((f, i) => ({ 'key': f, 'name': names[f] || f, 'slot': i + 1 }));
node.status({ fill: error === '' ? 'green' : 'red', shape: 'dot', text: msg.adco + ' ' + now.toLocaleTimeString('fr-FR') });

return [null, {
    'payload': {
        'error': error,
        'meters': flow.get('history_meters', 'memoryOnly') || [],
        'selected': msg.adco,
        'fields': fields,
        'periods': periods,
        'updated': now.toLocaleString('fr-FR')
    }
}];

// Watch the TIC reading of each serial port
// input: valid frame (parse output 1), bad frame (parse output 2, catch), tick (inject)
// output 1: FAULT entity to MQTT (0 / 1) / output 2: serial control (close then reopen the port)

const BAD_LIMIT = 5;      // consecutive bad frames before fault
const SILENCE = 60000;    // ms without valid frame before fault (port that already worked)
const RECOVER = 3;        // consecutive valid frames to clear fault
const RESET_MIN = 60000;  // first delay between two port resets
const RESET_MAX = 600000; // max delay between two port resets
const REOPEN = 3000;      // ms between port close and reopen

const topic = global.get('mqtt.topic', 'default') || '';
const source = 'teleinfo';
const now = Date.now();

let started = context.get('started', 'memoryOnly');
if (typeof started !== 'number') {
    started = now;
    context.set('started', started, 'memoryOnly');
}
let ports = context.get('ports', 'memoryOnly') || {};
// meter address of each port, kept across restarts to detect a port that never comes back
let known = context.get('known', 'default') || {};

function state(port) {
    if (typeof ports[port] !== 'object') {
        ports[port] = { 'bad': 0, 'good': 0, 'last': started, 'fault': 0, 'resets': 0, 'next': 0, 'reason': '' };
    }

    return ports[port];
}

// Frame received
if (msg.topic !== 'tick' && typeof msg.port === 'string' && msg.port !== '') {
    const s = state(msg.port);
    const p = msg.payload;
    if (typeof p === 'object' && p !== null && typeof p.ADCO === 'object' && p.ADCO.raw) {
        s.bad = 0;
        s.good++;
        s.last = now;
        if (known[msg.port] !== p.ADCO.raw) {
            known[msg.port] = p.ADCO.raw;
            context.set('known', known, 'default');
        }
        if (s.fault === 1 && s.good >= RECOVER) {
            s.fault = 0;
            s.resets = 0;
            s.next = 0;
            node.warn('TIC ' + msg.port + ' : lecture rétablie');
        }
    } else {
        s.bad++;
        s.good = 0;
        s.reason = String(p);
    }
}

let text = [];
let fill = 'green';
for (const port of new Set([...Object.keys(known), ...Object.keys(ports)])) {
    const s = state(port);
    const adco = known[port] || '';

    // Enter fault
    if (s.fault === 0 && (s.bad >= BAD_LIMIT || (adco !== '' && now - s.last > SILENCE))) {
        s.fault = 1;
        s.good = 0;
        s.resets = 0;
        s.next = now;
        node.warn('TIC ' + port + ' : lecture en défaut, ' + (s.bad >= BAD_LIMIT
            ? s.bad + ' trames mal décodées (' + s.reason + ')'
            : 'aucune trame valide depuis ' + Math.round((now - s.last) / 1000) + ' s'));
    }

    // Reset the port: close then reopen it, like unplugging the USB cable
    if (s.fault === 1 && now >= s.next) {
        node.send([null, { 'port': port, 'payload': { 'enabled': false } }]);
        setTimeout(() => node.send([null, { 'port': port, 'payload': { 'enabled': true } }]), REOPEN);
        s.resets++;
        s.bad = 0;
        s.next = now + Math.min(RESET_MIN * Math.pow(2, s.resets - 1), RESET_MAX);
        node.warn('TIC ' + port + ' : réouverture du port (essai ' + s.resets + ')');
    }

    // Publish on change (and after the daily reset of last values)
    const key = 'last["' + adco + '_FAULT"]';
    if (adco !== '' && topic !== '' && flow.get(key, 'memoryOnly') !== String(s.fault)) {
        flow.set(key, String(s.fault), 'memoryOnly');
        node.send([{
            'topic': [topic, 'get', source, adco, 'FAULT'].join('/'),
            'payload': String(s.fault)
        }, null]);
    }

    if (s.fault === 1) {
        fill = 'red';
    }
    text.push(port.replace('/dev/', '') + (s.fault === 1 ? ' défaut (' + s.resets + ')' : ' ok'));
}

context.set('ports', ports, 'memoryOnly');
node.status({ 'fill': fill, 'shape': 'dot', 'text': text.length ? text.join(', ') : 'en attente' });

return;
